                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "power" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Who can block an 85% special majority"
            subtitle="Solo vs coalition arithmetic under the Fund???s hardest rule"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={BLOCKING_POWER} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 22]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={48}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v)), "Vote weight"]}
                    labelFormatter={(_, p) =>
                      String(
                        (p as { payload?: { label?: string } }[])?.[0]?.payload
                          ?.label ?? "",
                      )
                    }
                  />
                  <Bar dataKey="votePct" radius={[0, 4, 4, 0]}>
                    {BLOCKING_POWER.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Dashed mental line at {HEADLINE.imfBlockThresholdPct}% ??? only US
              and the EU-5 cluster clear it alone in this panel.
            </p>
          </ChartCard>

          <ChartCard
            title="UNSC veto use (practice concentration)"
            subtitle="Charter already concentrates 100% of vetoes in five seats"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={VETO_SERIES}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
                  <Tooltip />
                  <Area
                    type="monotone"
                    dataKey="ru"
                    stackId="v"
                    fill="#e11d48"
                    stroke="#e11d48"
                    name="Russia"
                  />
                  <Area
                    type="monotone"
                    dataKey="us"
                    stackId="v"
                    fill="#0ea5e9"
                    stroke="#0ea5e9"
                    name="US"
                  />
                  <Area
                    type="monotone"
                    dataKey="cn"
                    stackId="v"
                    fill="#f59e0b"
                    stroke="#f59e0b"
                    name="China"
                  />
                  <Area
                    type="monotone"
                    dataKey="uk"
                    stackId="v"
                    fill="#64748b"
                    stroke="#64748b"
                    name="UK"
                  />
                  <Area
                    type="monotone"
                    dataKey="fr"
                    stackId="v"
                    fill="#14b8a6"
                    stroke="#14b8a6"
                    name="France"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Seat share vs veto share"
            subtitle="P5 are 33% of seats and 100% of negative rights"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[
                    {
                      label: "P5 seat share",
                      value: HEADLINE.unscSeatSharePct,
                      fill: "#8b5cf6",
                    },
                    {
                      label: "P5 veto share",
                      value: HEADLINE.unscVetoTop5Pct,
                      fill: "#f43f5e",
                    },
                  ]}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v) => [fmtPct(Number(v)), "Share"]} />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    <Cell fill="#8b5cf6" />
                    <Cell fill="#f43f5e" />
