"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  BLOCKING_POWER,
  CONCENTRATION_CURVE,
  CONCENTRATION_DELTAS,
  CONSENT_METERS,
  CONSENT_PATH,
  GAP_SCATTER,
  HEADLINE,
  HHI_BY_LENS,
  INSTITUTION_COMPARE,
  REGION_BUCKETS,
  SCOREBOARD,
  SOURCE_NOTE,
  TOP_K_LADDER,
  VETO_SERIES,
  VOTE_SHARES,
  fmtPct,
  fmtPp,
  fmtHhi,
} from "@/data/geopolitics-institutions-concentration-2026q3-data";

// viz-types: HHI bars, delta dumbbells, Lorenz area+line, ranked share bars, consent path lines, institution compare bars, region donut, veto stacked area, vote??GDP scatter, blocking bars | layout: default

type ViewId = "scoreboard" | "ladder" | "consent" | "power";
type LadderMetric = "imfVotePct" | "ibrdVotePct" | "cumulativeImfPct";
type CompareMetric = "top1Pct" | "top3Pct" | "top5Pct" | "hhiProxy";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
