              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={VETO_SERIES}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
                  <Tooltip />
                  <Area
                    type="monotone"
                    dataKey="ru"
                    stackId="v"
                    fill="#e11d48"
                    stroke="#e11d48"
                    name="Russia"
                  />
                  <Area
                    type="monotone"
                    dataKey="us"
                    stackId="v"
                    fill="#0ea5e9"
                    stroke="#0ea5e9"
                    name="US"
                  />
                  <Area
                    type="monotone"
                    dataKey="cn"
                    stackId="v"
                    fill="#f59e0b"
                    stroke="#f59e0b"
                    name="China"
                  />
                  <Area
                    type="monotone"
                    dataKey="uk"
                    stackId="v"
                    fill="#64748b"
                    stroke="#64748b"
                    name="UK"
                  />
                  <Area
                    type="monotone"
                    dataKey="fr"
                    stackId="v"
                    fill="#14b8a6"
                    stroke="#14b8a6"
                    name="France"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Seat share vs veto share"
            subtitle="P5 are 33% of seats and 100% of negative rights"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[
                    {
                      label: "P5 seat share",
                      value: HEADLINE.unscSeatSharePct,
                      fill: "#8b5cf6",
                    },
                    {
                      label: "P5 veto share",
                      value: HEADLINE.unscVetoTop5Pct,
                      fill: "#f43f5e",
                    },
                  ]}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v) => [fmtPct(Number(v)), "Share"]} />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    <Cell fill="#8b5cf6" />
                    <Cell fill="#f43f5e" />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Coalition notes"
            subtitle="Consent status among blocking clusters"
          >
            <ul className="space-y-2 text-sm text-slate-700">
              {BLOCKING_POWER.map((b) => (
                <li key={b.id} className="flex gap-2">
                  <span
                    className="mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full"
                    style={{ background: b.fill }}
                  />
                  <span>
                    <span className="font-semibold text-slate-900">
                      {b.label}
                    </span>{" "}
                    ({fmtPct(b.votePct)})
                    {b.canBlockAlone ? " ??? can block alone" : " ??? needs partners"}
                    . {b.note}
                  </span>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

